descriptor.templateCss:
/* SUNKUU 360 — Template Piscina · CSS v3
   Tokens: --navy #00008C · --teal #00EBC8 · --bg #EBF0F7 · --brd #D4E0EE
   v3: variables :root, hardcoded→tokens, emojis→Material Icons,
       Caldero eliminado, legibilidad mejorada, badges normalizados */

#sp-root {
  --navy: #00008C;
  --teal: #00EBC8;
  --bg:   #EBF0F7;
  --surf: #FFFFFF;
  --pri:  #0D1B2E;
  --sec:  #5A6E8A;
  --ter:  #96AABF;
  --brd:  #D4E0EE;
  --pos:  #10B981;
  --neg:  #EF4444;
  --warn: #F59E0B;
  --ind:  #6366F1;
  --shd:  0 1px 3px rgba(13,27,46,.06), 0 8px 28px rgba(13,27,46,.08);
}

*{box-sizing:border-box;margin:0;padding:0}
#sp-root{font-family:system-ui,-apple-system,'Segoe UI',sans-serif;background:var(--bg);min-height:100vh;display:flex;flex-direction:column}

/* ── HEADER ──────────────────────────────────────────────── */
#sp-hdr{background:var(--navy);box-shadow:0 2px 14px rgba(0,0,0,.32);position:sticky;top:0;z-index:20}
.hdr-main{max-width:1440px;margin:0 auto;padding:0 24px;height:56px;display:flex;align-items:center;justify-content:space-between}
.hdr-left{display:flex;align-items:center;gap:12px}
#btn-fleet{background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.14);border-radius:8px;padding:6px 11px;cursor:pointer;color:rgba(255,255,255,.8);font-size:12px;font-weight:600;font-family:inherit;transition:all .15s}
#btn-fleet:hover{background:rgba(255,255,255,.14);color:white}
.sp-sep{width:1px;height:22px;background:rgba(255,255,255,.1)}
.sp-logo{display:flex;align-items:center;gap:9px;font-weight:800;font-size:17px;letter-spacing:-.01em;color:white}
.logo-t{color:var(--teal)}
.logo-s{font-weight:400;font-size:10px;color:rgba(255,255,255,.35);margin-left:4px;letter-spacing:.05em}
.hdr-inst-badge{background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.14);border-radius:8px;padding:6px 12px;display:flex;gap:7px;align-items:center}
.hdr-dot{width:6px;height:6px;border-radius:50%;background:var(--pos);box-shadow:0 0 4px rgba(16,185,129,.8)}
#hdr-inst-name{font-size:13px;font-weight:700;color:white}
.hdr-caret{font-size:9px;color:rgba(255,255,255,.4)}
.hdr-right{display:flex;align-items:center;gap:14px}
.hdr-status-wrap{display:flex;align-items:center;gap:5px}
.hdr-sdot{width:7px;height:7px;border-radius:50%;background:var(--pos);box-shadow:0 0 6px rgba(16,185,129,.7)}
#last-sec{font-size:12px;color:rgba(255,255,255,.75)}

/* Nav */
.hdr-nav{max-width:1440px;margin:0 auto;padding:0 24px;height:38px;display:flex;align-items:center;gap:2px;border-top:1px solid rgba(255,255,255,.07)}
.anc{padding:0 15px;height:100%;border:none;cursor:pointer;font-size:12px;font-weight:600;background:transparent;color:rgba(255,255,255,.55);border-bottom:2.5px solid transparent;transition:all .15s;font-family:inherit}
.anc:hover{color:rgba(255,255,255,.8)}
.anc.active{color:white;border-bottom-color:var(--teal)}
.hdr-rt-pill{margin-left:auto;display:flex;align-items:center;gap:5px;background:rgba(0,235,200,.1);border:1px solid rgba(0,235,200,.2);border-radius:7px;padding:4px 11px}
.rt-dot{width:6px;height:6px;border-radius:50%;background:var(--teal);box-shadow:0 0 5px rgba(0,235,200,.8)}
.hdr-rt-pill span{font-size:11px;font-weight:600;color:var(--teal)}

/* ── BODY & SECTIONS ────────────────────────────────────── */
#sp-body{max-width:1440px;margin:0 auto;padding:4px 24px 60px;width:100%}
.sp-sec{margin-bottom:8px}
.sec-hdr{display:flex;align-items:flex-start;gap:14px;margin:30px 0 16px}
.sec-num{width:34px;height:34px;border-radius:9px;flex-shrink:0;background:linear-gradient(135deg,var(--navy),#0a0abb);display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:800;color:var(--teal);box-shadow:0 2px 10px rgba(0,0,140,.35)}
.sec-txt{flex:1}
.sec-title{font-size:17px;font-weight:800;color:var(--navy);letter-spacing:-.02em;line-height:1}
.sec-sub{font-size:12px;color:var(--sec);margin-top:5px}

/* ── KPI CARDS ──────────────────────────────────────────── */
.kpi-row4{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:14px}
.kpi-card{background:var(--surf);border-radius:16px;border:1px solid var(--brd);border-top:3px solid var(--brd);box-shadow:var(--shd);padding:18px 20px 0;overflow:hidden}
.kpi-top{display:flex;align-items:center;gap:8px;margin-bottom:10px}

/* Ícono Material Icon en KPI */
.kpi-top-ico{
  font-family:'Material Icons';font-size:20px;
  color:var(--ter);font-style:normal;font-weight:normal;
  line-height:1;user-select:none;
}

/* Label KPI: texto descriptivo, sin unidades → uppercase ok */
.kpi-lbl{font-size:10px;font-weight:700;color:var(--sec);letter-spacing:.06em;text-transform:uppercase}
.kpi-vrow{display:flex;align-items:baseline;gap:5px;margin-bottom:8px}
.kpi-big{font-size:36px;font-weight:800;color:var(--pri);letter-spacing:-.04em;line-height:1;font-variant-numeric:tabular-nums}
.kpi-unit{font-size:14px;font-weight:600;color:var(--sec)}
/* Chip normalizado */
.kpi-chip{display:inline-block;padding:4px 10px;border-radius:20px;font-size:10px;font-weight:700;margin-bottom:12px;background:rgba(0,235,200,.1);color:var(--navy);border:1px solid rgba(0,235,200,.25)}
.kpi-chip.ok   {background:rgba(16,185,129,.1);color:#065F46;border-color:rgba(16,185,129,.22)}
.kpi-chip.warn {background:rgba(245,158,11,.1);color:#92400E;border-color:rgba(245,158,11,.22)}
.kpi-chip.alert{background:rgba(239,68,68,.1);color:#991B1B;border-color:rgba(239,68,68,.22)}
.kpi-chip.off  {background:rgba(90,110,138,.1);color:var(--sec);border-color:rgba(90,110,138,.2)}

.kpi-spark{height:48px;margin:0 -20px}
.bat-wrap{margin:0 -20px;padding:0 20px 14px}
.bat-track{height:6px;border-radius:3px;background:var(--brd);overflow:hidden;margin-bottom:6px}
.bat-fill{height:100%;border-radius:3px;transition:width .4s}
.bat-meta{display:flex;justify-content:space-between}
.bat-meta span{font-size:10px;color:var(--sec)}

/* ── COMPARISON CARDS ───────────────────────────────────── */
.cmp-row3{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-bottom:14px}
.cmp-card{background:var(--surf);border-radius:14px;border:1px solid var(--brd);box-shadow:var(--shd);padding:16px 18px;display:flex;gap:14px;align-items:center}
.cmp-icon{
  width:42px;height:42px;border-radius:10px;flex-shrink:0;
  background:rgba(0,0,140,.08);border:1px solid rgba(0,0,140,.15);
  display:flex;align-items:center;justify-content:center;
  font-family:'Material Icons';font-size:20px;
  color:var(--navy);font-style:normal;font-weight:normal;
  line-height:1;user-select:none;transition:all .3s
}
.cmp-lbl{font-size:11px;color:var(--sec);margin-bottom:3px}
.cmp-val{font-size:18px;font-weight:800;color:var(--pri)}
.cmp-sub{font-size:11px;color:var(--sec);margin-top:2px}

/* ── INTELLIGENCE CARD ──────────────────────────────────── */
.ic-card{background:linear-gradient(135deg,var(--navy) 0%,#0a0aaa 50%,#000f72 100%);border-radius:18px;padding:22px 26px;border:1px solid rgba(0,235,200,.22);box-shadow:0 6px 32px rgba(0,0,140,.30);margin-bottom:8px}
.ic-toprow{display:flex;align-items:center;justify-content:space-between;margin-bottom:16px;flex-wrap:wrap;gap:10px;text-align:left}
.ic-robot{
  width:40px;height:40px;border-radius:10px;
  background:rgba(0,235,200,.14);border:1px solid rgba(0,235,200,.28);
  display:flex;align-items:center;justify-content:center;
  font-family:'Material Icons';font-size:22px;
  color:var(--teal);font-style:normal;font-weight:normal;
  line-height:1;user-select:none;flex-shrink:0
}
.ic-badge{font-size:10px;font-weight:800;letter-spacing:.1em;text-transform:uppercase;color:var(--teal)}
.ic-date{font-size:10px;color:rgba(255,255,255,.45);margin-top:2px}
.ic-obj-pill{background:rgba(0,235,200,.12);border:1px solid rgba(0,235,200,.22);border-radius:8px;padding:5px 12px;font-size:10px;font-weight:700;color:rgba(0,235,200,.9);white-space:nowrap}
.ic-text{font-size:15px;font-weight:400;line-height:1.7;color:rgba(255,255,255,.92);margin:0 0 20px}
.ic-text strong{color:var(--teal)}
.ic-metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}
.ic-metric{background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.1);border-radius:12px;padding:12px 16px}
.ic-m-lbl{font-size:10px;color:rgba(255,255,255,.55);letter-spacing:.05em;margin-bottom:6px}
.ic-m-val{font-size:20px;font-weight:800;color:white;line-height:1;font-variant-numeric:tabular-nums}
.ic-m-sub{font-size:11px;color:rgba(255,255,255,.5);margin-top:5px}

/* ── CHART CARDS ────────────────────────────────────────── */
.chart-card{background:var(--surf);border-radius:16px;border:1px solid var(--brd);box-shadow:var(--shd);padding:20px}
.chart-tb{display:flex;align-items:center;justify-content:space-between;margin-bottom:16px;flex-wrap:wrap;gap:8px}
.tbtn-grp{display:flex;background:#F0F6FC;border-radius:9px;padding:3px;gap:1px}
.tbtn{padding:5px 14px;border-radius:6px;border:none;cursor:pointer;font-size:11px;font-weight:600;background:transparent;color:var(--sec);font-family:inherit;transition:all .15s}
.tbtn.active{background:var(--navy);color:white}
.tbtn:hover:not(.active){background:rgba(0,0,140,.07)}
.leg-row{display:flex;align-items:center;gap:12px;flex-wrap:wrap}
.leg-i{display:flex;align-items:center;gap:6px;font-size:11px;color:var(--sec)}
.leg-ln{width:20px;height:2.5px;border-radius:2px;flex-shrink:0}
.ch-wrap-260{height:260px;position:relative}
.ch-wrap-200{height:200px;position:relative}
.ch-lbl-sm{font-size:11px;font-weight:700;color:var(--sec);letter-spacing:.06em;text-transform:uppercase}
.ts-grid4{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:16px}
.ts-s{background:#F4F8FC;border-radius:10px;padding:11px 14px;border-left:3px solid var(--brd)}
.ts-lbl{font-size:11px;color:var(--sec);margin-bottom:2px}
.ts-val{font-size:15px;font-weight:800;color:var(--pri)}
.ts-sub{font-size:11px;color:var(--sec);margin-top:1px}

/* ── EQUIPMENT CARDS ────────────────────────────────────── */
.eq-grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
.eq-card{background:var(--surf);border-radius:16px;border:1px solid var(--brd);box-shadow:var(--shd);padding:20px}
.eq-hdr{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:14px}
.eq-lbl{font-size:11px;font-weight:700;color:var(--sec);text-transform:uppercase;letter-spacing:.07em}
.eq-dev{font-size:11px;color:var(--sec)}
.eq-srow{display:flex;align-items:center;gap:14px;margin-bottom:14px}
.eq-circle{
  width:56px;height:56px;border-radius:50%;flex-shrink:0;
  background:#F0F4F8;border:2px solid var(--brd);
  display:flex;align-items:center;justify-content:center;
  font-family:'Material Icons';font-size:26px;
  color:var(--ter);font-style:normal;font-weight:normal;
  line-height:1;user-select:none;transition:all .3s
}
.eq-circle.on{background:rgba(0,235,200,.1);border-color:rgba(0,235,200,.4);box-shadow:0 0 16px rgba(0,235,200,.3);color:var(--navy)}
.eq-ht{background:#F0F4F8;border:2px solid var(--brd)}
.eq-state{font-size:22px;font-weight:800;color:var(--sec);transition:color .3s}
.eq-state.on{color:var(--navy)}
.eq-sub{font-size:11px;color:var(--sec);margin-top:2px}
.eq-box{background:#F4F8FC;border-radius:10px;padding:10px 14px}
.eq-box-lbl{font-size:11px;color:var(--sec);margin-bottom:2px}
.eq-box-val{font-size:14px;font-weight:700;color:var(--pri)}

/* ── CONSUMPTION ────────────────────────────────────────── */
/* Con Caldero eliminado, cons-right solo tiene cost-card */
.cons-layout{display:grid;grid-template-columns:3fr 2fr;gap:18px}
.cs-row4{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-top:14px}
.cs-i{background:#F4F8FC;border-radius:9px;padding:10px 12px}
.cs-lbl{font-size:11px;color:var(--sec);margin-bottom:3px}
.cs-val{font-size:14px;font-weight:700;color:var(--pri);font-variant-numeric:tabular-nums}
.cons-right{display:flex;flex-direction:column;gap:14px}
.cost-card{background:var(--surf);border-radius:16px;border:1px solid var(--brd);box-shadow:var(--shd);padding:18px 20px}
.cost-top{display:flex;align-items:flex-start;gap:12px;margin-bottom:16px}
.cost-icon{width:36px;height:36px;border-radius:9px;flex-shrink:0;background:linear-gradient(135deg,var(--navy),#0a0abb);display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:800;color:var(--teal)}
.cost-title{font-size:13px;font-weight:800;color:var(--navy)}
.cost-sub{font-size:11px;color:var(--sec);margin-top:2px}
.cr{display:flex;justify-content:space-between;padding:8px 0;border-bottom:1px solid var(--brd)}
.cr:last-child{border-bottom:none}
.cr-l{font-size:12px;color:var(--sec)}
.cr-v{font-size:12px;font-weight:600;color:var(--pri);font-variant-numeric:tabular-nums}
.cr-hi .cr-l,.cr-hi .cr-v{font-size:13px;color:var(--navy);font-weight:700}

/* ── ALARMS ─────────────────────────────────────────────── */
.al-badge{margin-left:auto;padding:4px 10px;border-radius:20px;font-size:10px;font-weight:700;background:#ECFDF5;color:var(--pos);border:1px solid rgba(16,185,129,.22)}
.al-box{background:var(--surf);border-radius:16px;border:1px solid var(--brd);box-shadow:var(--shd);overflow:hidden}
.al-row{display:flex;align-items:center;gap:10px;padding:13px 18px;border-top:1px solid var(--brd)}
.al-row:first-child{border-top:none}
.al-dot{width:8px;height:8px;border-radius:50%;flex-shrink:0}
.al-info{flex:1;min-width:0}
.al-tipo{font-size:13px;font-weight:600;color:var(--pri)}
.al-fase{font-size:11px;color:var(--sec);margin-left:8px}
.al-fecha{font-size:11px;color:var(--sec);flex-shrink:0}
.al-res{font-size:10px;font-weight:700;padding:3px 9px;border-radius:6px;flex-shrink:0}

/* ── CONFIG + ACTIONS ───────────────────────────────────── */
.cfg-wrap{background:var(--surf);border-radius:14px;border:1px solid var(--brd);box-shadow:0 1px 3px rgba(13,27,46,.06);margin:20px 0;overflow:hidden}
.cfg-btn{width:100%;background:transparent;border:none;cursor:pointer;padding:14px 20px;display:flex;justify-content:space-between;align-items:center;font-size:13px;font-weight:700;color:var(--navy);font-family:inherit}
.cfg-btn:hover{background:rgba(0,0,140,.03)}
.cfg-arr{font-size:11px;color:var(--ter);transition:transform .2s}
.cfg-body{padding:0 20px 16px}
.cfg-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}
.cfg-item{background:#F4F8FC;border-radius:10px;padding:12px 14px}
.cfg-k{font-size:10px;color:var(--sec);margin-bottom:4px}
.cfg-v{font-size:13px;font-weight:700;color:var(--pri)}
.cfg-n{font-size:10px;color:#96AABF;margin-top:3px}

.act-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:20px}
.act-btn{border-radius:14px;padding:15px 20px;cursor:pointer;text-align:left;display:flex;align-items:center;gap:12px;transition:all .15s;font-family:inherit;border:1px solid transparent}
.act-navy  {background:rgba(0,0,140,.07);border-color:rgba(0,0,140,.15)}
.act-teal  {background:rgba(0,235,200,.07);border-color:rgba(0,235,200,.2)}
.act-indigo{background:rgba(99,102,241,.07);border-color:rgba(99,102,241,.18)}
.act-btn:hover{transform:translateY(-1px);box-shadow:0 4px 12px rgba(0,0,0,.08)}
.act-ico{
  font-family:'Material Icons';font-size:22px;
  font-style:normal;font-weight:normal;
  line-height:1;user-select:none;color:inherit;flex-shrink:0
}
.act-t{font-size:13px;font-weight:700}
.act-s{font-size:11px;color:var(--sec);margin-top:2px}

/* ── DROPDOWN INSTALACIONES ────────────────────────────── */
.inst-dd{position:absolute;top:calc(100% + 8px);left:0;min-width:220px;background:var(--surf);border-radius:12px;border:1px solid var(--brd);box-shadow:0 8px 28px rgba(0,0,0,.16);z-index:100;overflow:hidden;padding:6px 0}
.idd-title{font-size:10px;font-weight:700;color:var(--ter);letter-spacing:.08em;text-transform:uppercase;padding:8px 16px 4px}
.idd-item{padding:10px 16px;font-size:12px;font-weight:600;color:var(--pri);cursor:pointer;display:flex;align-items:center;gap:8px;transition:background .12s}
.idd-item:hover{background:rgba(0,235,200,.08);color:var(--navy)}
.idd-dot{width:7px;height:7px;border-radius:50%;background:var(--pos);box-shadow:0 0 4px rgba(16,185,129,.7);flex-shrink:0}
.idd-current{padding:10px 16px;font-size:12px;font-weight:700;color:var(--navy);display:flex;align-items:center;gap:8px;background:rgba(0,235,200,.08);cursor:default;border-bottom:1px solid var(--brd)}
.idd-check{font-size:11px;color:var(--teal);flex-shrink:0}
.idd-here{margin-left:auto;font-size:9px;font-weight:600;color:rgba(0,235,200,.8);letter-spacing:.04em;white-space:nowrap}

/* ── RESPONSIVE ─────────────────────────────────────────── */
@media(max-width:900px){
  #sp-body{padding:14px 16px 24px}
  .kpi-row4,.eq-grid3,.act-grid{grid-template-columns:repeat(2,1fr)}
  .cons-layout,.cmp-row3{grid-template-columns:1fr}
  .ts-grid4,.ic-metrics{grid-template-columns:repeat(2,1fr)}
  .cfg-grid{grid-template-columns:repeat(2,1fr)}
}

descriptor.controllerScript:
/**
 * SUNKUU 360 — Template Piscina · JS v2B
 * ThingsBoard PE 4.3.0PE
 *
 * v2B: Operational Intelligence Layer
 *  · classifyPiscState(): Estable / Atención / Sin histórico / Sin señal
 *  · tryIC() reescrita con card ejecutiva unificada (badge + título + impacto + métricas)
 *
 * Recurso requerido:
 *   https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js
 */
self.onInit = function () {
  var ctx = self.ctx;

  /* ── 1. CONFIG ─────────────────────────────────────────── */
  var CAL_ID = '', ILU_ID = '', AMB_ID = '';
  var TARIFA = 0.65, INSTALL_NAME = 'Piscina';
  var TEMP_OBJ = 33, TEMP_MIN = 30, TEMP_MAX = 35;

  if (ctx.settings && ctx.settings.calentadorId) {
    CAL_ID       = ctx.settings.calentadorId.trim();
    ILU_ID       = (ctx.settings.iluminacionId || '').trim();
    AMB_ID       = (ctx.settings.ambienteId    || '').trim();
    TARIFA       = ctx.settings.tarifa_kwh    != null ? ctx.settings.tarifa_kwh    : 0.65;
    INSTALL_NAME = ctx.settings.installName   || 'Piscina';
    TEMP_OBJ     = ctx.settings.tempObjetivo  != null ? ctx.settings.tempObjetivo  : 33;
    TEMP_MIN     = ctx.settings.tempMinAlerta != null ? ctx.settings.tempMinAlerta : 30;
    TEMP_MAX     = ctx.settings.tempMaxAlerta != null ? ctx.settings.tempMaxAlerta : 35;
  }
  if (!CAL_ID) {
    var raw = (ctx.settings && ctx.settings.cardHtml) || '';
    var m   = raw.match(/<!--CFG:([\s\S]*?)-->/);
    if (m) {
      try {
        var c    = JSON.parse(m[1]);
        CAL_ID       = (c.cal  || '').trim();
        ILU_ID       = (c.ilu  || '').trim();
        AMB_ID       = (c.amb  || '').trim();
        TARIFA       = parseFloat(c.t)    || 0.65;
        INSTALL_NAME = c.n               || 'Piscina';
        TEMP_OBJ     = parseFloat(c.tobj) || 33;
        TEMP_MIN     = parseFloat(c.tmin) || 30;
        TEMP_MAX     = parseFloat(c.tmax) || 35;
      } catch (e) { console.warn('[PISC] CFG error:', e); }
    }
  }

  var EXPORT_DASH = '75c7e760-3200-11f1-a6d8-33f75efe8b97';
  ctx.$container.css({ 'overflow-y': 'auto', 'height': '100%' });

  if (!CAL_ID) {
    ctx.$container[0].innerHTML =
      '<div style="display:flex;align-items:center;justify-content:center;height:200px;font-family:system-ui;color:#5A6E8A;flex-direction:column;gap:12px">' +
      '<span style="font-size:32px">⚙</span><strong>Configura los UUIDs en el CFG o Settings</strong>' +
      '<span style="font-size:12px">Apariencia → HTML → <!--CFG:{...}--></span></div>';
    return;
