  /* ── 3. HELPERS ────────────────────────────────────────── */
  function nowMs()      { return Date.now(); }
  function todayStart() { var d=new Date(); d.setHours(0,0,0,0); return d.getTime(); }
  function ydayStart()  { return todayStart()-86400000; }
