  function tsUrl(dev,keys,s,e,iv,ag,lim){
    var u='/api/plugins/telemetry/DEVICE/'+dev+'/values/timeseries?keys='+keys;
    if(s!==undefined) u+='&startTs='+s+'&endTs='+e;
    if(iv) u+='&interval='+iv+'&agg='+(ag||'AVG');
    if(lim) u+='&limit='+lim;
