  /* ── 5. LAST SEEN ──────────────────────────────────────── */
  function updateLastSeen(){
    var now=new Date();
    var t=pad(now.getHours())+':'+pad(now.getMinutes())+':'+pad(now.getSeconds());
    /* Piscina: umbrales más amplios — H&T G3 tiene ciclo sueño ~2h */
    /* Atención: >12h sin datos. Alerta: >30h sin datos */
    var WARN_MS  = 12 * 3600000;
    var ALERT_MS = 30 * 3600000;
    if(D.lastRealTs){
      var age=Math.floor((now.getTime()-D.lastRealTs)/1000);
      var ageStr;
      if(age<60)        ageStr='hace '+age+' seg';
      else if(age<3600) ageStr='hace '+Math.floor(age/60)+' min';
      else              ageStr='hace '+Math.floor(age/3600)+'h '+Math.floor((age%3600)/60)+' min';
      var lastTs=el('last-ts');
      if(lastTs){
        lastTs.textContent='Actualizado '+ageStr+' · ';
        lastTs.style.color=age*1000>ALERT_MS?'#EF4444':age*1000>WARN_MS?'#F59E0B':'';
      }
      var onlineDot=document.querySelector('.hdr-sdot');
      var onlineTxt=document.querySelector('.hdr-ts');
      if(age*1000>ALERT_MS){
        if(onlineDot) onlineDot.style.background='#EF4444';
        if(onlineTxt) onlineTxt.textContent='Sin datos · '+ageStr;
      } else if(age*1000>WARN_MS){
        if(onlineDot) onlineDot.style.background='#F59E0B';
        if(onlineTxt) onlineTxt.textContent='Datos con retraso · '+ageStr;
      } else {
        if(onlineDot) onlineDot.style.background='#10B981';
        if(onlineTxt) onlineTxt.textContent='En línea · '+t;
      }
    } else {
      var lastTs2=el('last-ts');
      if(lastTs2) lastTs2.textContent='Actualizando… · ';
    }
  }

  /* ── 6. SPARKLINE ──────────────────────────────────────── */
  function spark(cid,data,color){
    var w=el(cid); if(!w||!data||data.length<2) return;
    var W=w.clientWidth||160,H=48,mn=Math.min.apply(null,data),mx=Math.max.apply(null,data),rng=mx-mn||1;
    var pts=data.map(function(v,i){return[+(i/(data.length-1)*W).toFixed(1),+(H-2-((v-mn)/rng)*(H-4)).toFixed(1)];});
    var ln=pts.map(function(p,i){return(i===0?'M':'L')+p[0]+','+p[1];}).join(' ');
    var uid='g'+Math.random().toString(36).slice(2,7);
    w.innerHTML='<svg viewBox="0 0 '+W+' '+H+'" width="100%" height="'+H+'" preserveAspectRatio="none" style="display:block">'+
      '<defs><linearGradient id="'+uid+'" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="'+color+'" stop-opacity=".3"/><stop offset="100%" stop-color="'+color+'" stop-opacity="0"/></linearGradient></defs>'+
      '<path d="'+ln+' L'+W+','+H+' L0,'+H+' Z" fill="url(#'+uid+')"/>'+
      '<path d="'+ln+'" fill="none" stroke="'+color+'" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></svg>';
  }

