  /* ── 8. RENDER SEC01 ───────────────────────────────────── */
  function renderSec01(){
    var tp=lat(D.pisc,'temperatura_sonda');
    if(tp!==null){
      set('kv-tp',fmtT(tp));
      var chip=el('kch-tp'), dif=tp-TEMP_OBJ;
      if(chip){
        if(tp>=TEMP_MAX)      {chip.textContent='⚠ Sobre el máximo ('+fmtT(tp)+'°C)';chip.style.cssText=chipCSS('#EF4444');}
        else if(tp<TEMP_MIN)  {chip.textContent='⚠ Bajo el mínimo ('  +fmtT(tp)+'°C)';chip.style.cssText=chipCSS('#F59E0B');}
        else if(dif>=0)       {chip.textContent='✓ Sobre objetivo (+'+dif.toFixed(1)+'°C)';chip.style.cssText=chipCSS('#10B981');}
        else                  {chip.textContent='↓ Bajo objetivo ('+dif.toFixed(1)+'°C)';chip.style.cssText=chipCSS('#F59E0B');}
      }
    }
    var calOn=lat(D.pisc,'estado_salida');
    if(calOn!==null){
      var cv=el('cmp-cal'); if(cv){cv.textContent=calOn?'Encendido':'Apagado';cv.style.color=calOn?'#00008C':'#5A6E8A';}
      var ci=el('cmp-icon-cal'); if(ci){ci.style.background=calOn?'rgba(0,235,200,.1)':'rgba(0,0,140,.08)';ci.style.borderColor=calOn?'rgba(0,235,200,.3)':'rgba(0,0,140,.15)';}
    }
    renderDif();
  }

  function chipCSS(c){return 'display:inline-block;padding:4px 10px;border-radius:20px;font-size:10px;font-weight:700;margin-bottom:12px;background:'+c+'18;color:'+c+';border:1px solid '+c+'28';}

  function renderSec01Amb(){
    var ta=lat(D.amb,'temperatura'),hum=lat(D.amb,'humedad'),bat=lat(D.amb,'bateria_porcentaje'),batV=lat(D.amb,'bateria_voltaje');
    if(ta!==null)  set('kv-ta',fmtT(ta));
    if(hum!==null){set('kv-hum',hum.toFixed(0));var ch=el('kch-hum');if(ch)ch.textContent=hum>70?'⚠ Humedad alta':hum<40?'Baja':'✓ Normal';}
    if(bat!==null){
      set('kv-bat',bat.toFixed(0));
      var col=bat>=60?'#10B981':bat>=30?'#F59E0B':'#EF4444';
      var fill=el('bat-fill');if(fill){fill.style.width=bat+'%';fill.style.background=col;}
      var kb=el('kch-bat');if(kb){kb.textContent=bat>=60?'● Carga buena':bat>=30?'⚠ Carga baja':'⚠ Batería crítica';kb.style.cssText=chipCSS(col);}
    }
    if(batV!==null) set('bat-v',batV.toFixed(2)+' V');
    renderDif();
