  function renderDif(){
    var tp=lat(D.pisc,'temperatura_sonda'),ta=lat(D.amb,'temperatura');
    if(tp!==null&&ta!==null){
      var df=tp-ta;
      set('cmp-dif','+'+df.toFixed(1)+'°C');
      set('cmp-dif-s',fmtT(tp)+'°C – '+fmtT(ta)+'°C · '+(df>8?'Retención estable':'Pérdida elevada'));
      set('ts-dif','+'+df.toFixed(1)+'°C');
