  function renderSec01YdCmp(){
    if(D.piscYd===null||lat(D.pisc,'temperatura_sonda')===null) return;
    var t=D.pisc.temperatura_sonda,td=D.piscYd,dif=t-td,up=dif>=0,col=up?'#EF4444':'#10B981';
    set('cmp-ayer',(up?'↑ +':'↓ ')+Math.abs(dif).toFixed(1)+'°C');
