    if(ic){ic.textContent=up?'trending_up':'trending_down';ic.style.fontFamily='Material Icons';ic.style.background=col+'14';ic.style.color=col;ic.style.borderColor=col+'22';}
  }

  /* ── 9. 2B — ESTADO OPERATIVO PISCINA ─────────────────── */
  function classifyPiscState(){
    var tCur=lat(D.pisc,'temperatura_sonda'), calOn=lat(D.pisc,'estado_salida'), ta=lat(D.amb,'temperatura');

    if(tCur===null){
      return {level:'sin-senal',badge:'Sin señal del sensor',
        title:'No se reciben datos del sensor de temperatura.',
        impact:'No es posible evaluar el estado de la piscina ni la operación del calentador.',
        action:'Verificar conectividad del dispositivo Shelly Plus 1.',detail:null};
    }
    if(!D.ok.piscH||D.piscH.length<3){
      return {level:'sin-historico',badge:'Sin histórico suficiente',
        title:'Monitoreo activo. Temperatura actual: '+fmtT(tCur)+'°C. Aún no hay suficiente histórico para detectar patrones.',
        impact:null,
        action:'El análisis de tendencia estará disponible tras las primeras horas de datos.',
        detail:buildPiscDetail(tCur,calOn,ta)};
    }

    var reasons=[], impacts=[];
    if(tCur>TEMP_MAX){reasons.push('Temperatura por encima del máximo configurado ('+fmtT(tCur)+'°C > '+TEMP_MAX+'°C)');impacts.push('Puede afectar la experiencia del huésped y la integridad de los equipos.');}
    if(tCur<TEMP_MIN){reasons.push('Temperatura por debajo del mínimo configurado ('+fmtT(tCur)+'°C < '+TEMP_MIN+'°C)');impacts.push('La piscina está fuera del rango confortable para el huésped.');}
    if(calOn===false&&tCur<TEMP_OBJ-1){reasons.push('Calentador apagado con temperatura '+(TEMP_OBJ-tCur).toFixed(1)+'°C bajo el objetivo');impacts.push('El calentador debería estar activo para alcanzar el objetivo configurado.');}

    if(reasons.length>0){
      return {level:'atencion',badge:'Atención requerida',
        title:reasons[0]+'.',impact:impacts[0],
        action:reasons.length>1?'Se detectaron '+reasons.length+' condiciones que requieren revisión.':'Monitorear evolución en los próximos 30 minutos.',
        detail:buildPiscDetail(tCur,calOn,ta)};
    }

    var dif2=tCur-TEMP_OBJ;
    var ctx2=Math.abs(dif2)<0.5?'La temperatura coincide con el objetivo configurado ('+TEMP_OBJ+'°C).':dif2>=0?'La temperatura se mantiene '+dif2.toFixed(1)+'°C sobre el objetivo configurado.':'La temperatura está '+Math.abs(dif2).toFixed(1)+'°C bajo el objetivo'+(calOn?' — calentador activo.':' — calentador inactivo, operando por inercia térmica.');
    return {level:'estable',badge:'Operación estable',title:'Piscina en condición operativa. '+ctx2,impact:null,action:null,detail:buildPiscDetail(tCur,calOn,ta)};
  }

  function buildPiscDetail(tCur,calOn,ta){
    var items=[];
    if(tCur!==null) items.push({l:'Temperatura piscina',v:fmtT(tCur)+'°C',warn:tCur<TEMP_MIN||tCur>TEMP_MAX});
    items.push({l:'Calentador',v:calOn===null?'—':(calOn?'Encendido':'Apagado'),warn:calOn===false&&tCur!==null&&tCur<TEMP_OBJ-1});
    if(ta!==null) items.push({l:'Temp. ambiente',v:fmtT(ta)+'°C',warn:false});
    if(tCur!==null&&ta!==null) items.push({l:'Diferencial',v:'+'+(tCur-ta).toFixed(1)+'°C',warn:false});
    return items;
  }

  function tryIC(){
    if(!D.ok.pisc) return;
    var tCur=lat(D.pisc,'temperatura_sonda'),calOn=lat(D.pisc,'estado_salida'),ta=lat(D.amb,'temperatura');
    var state=classifyPiscState();
    var BAND={
      'estable':       {color:'#10B981',icon:'check_circle',   label:'OPERACIÓN ESTABLE'},
      'atencion':      {color:'#F59E0B',icon:'warning_amber',  label:'ATENCIÓN REQUERIDA'},
      'sin-historico': {color:'rgba(255,255,255,.28)',icon:'hourglass_empty',label:'SIN HISTÓRICO SUFICIENTE'},
      'sin-senal':     {color:'rgba(255,255,255,.18)',icon:'signal_wifi_off',label:'SIN SEÑAL'}
    };
    var band=BAND[state.level]||BAND['sin-historico'];
    var now=new Date(),t=pad(now.getHours())+':'+pad(now.getMinutes())+':'+pad(now.getSeconds());
    var bandaHtml=
      '<div style="background:'+band.color+';border-radius:10px;padding:10px 16px;display:flex;align-items:center;gap:10px;margin-bottom:16px">'+
        '<span style="font-family:Material Icons;font-size:18px;color:white;line-height:1">'+band.icon+'</span>'+
        '<span style="font-size:12px;font-weight:800;letter-spacing:.08em;color:white;flex:1">'+band.label+'</span>'+
        '<span style="font-size:11px;color:rgba(255,255,255,.75);font-variant-numeric:tabular-nums">'+t+'</span>'+
      '</div>';
    var bodyHtml='<div style="font-size:13px;font-weight:500;color:rgba(255,255,255,.92);line-height:1.65;margin-bottom:'+(state.impact||state.action?'10px':'0')+'">'+state.title+'</div>';
    if(state.impact)bodyHtml+='<div style="margin-top:8px;font-size:12px;color:rgba(255,255,255,.6);line-height:1.6;margin-bottom:'+(state.action?'6px':'0')+'"><span style="font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:rgba(255,255,255,.3);margin-right:6px">Impacto potencial:</span>'+state.impact+'</div>';
    if(state.action)bodyHtml+='<div style="margin-top:6px;font-size:12px;color:rgba(255,255,255,.5);line-height:1.6"><span style="font-family:Material Icons;font-size:12px;vertical-align:middle;margin-right:4px;color:rgba(255,255,255,.35)">arrow_forward</span>'+state.action+'</div>';
    var detailHtml='';
    if(state.detail&&state.detail.length>0){
      detailHtml='<div style="display:flex;flex-wrap:wrap;gap:8px;margin-top:16px;padding-top:14px;border-top:1px solid rgba(255,255,255,.1)">'+
        state.detail.map(function(m){
          var wc=m.warn?'#FBBF24':'rgba(255,255,255,.75)',wb=m.warn?'rgba(245,158,11,.18)':'rgba(255,255,255,.07)',wd=m.warn?'rgba(245,158,11,.35)':'rgba(255,255,255,.1)';
          return '<div style="padding:7px 12px;border-radius:8px;background:'+wb+';border:1px solid '+wd+'">'+
            '<div style="font-size:9px;font-weight:600;text-transform:uppercase;letter-spacing:.05em;color:rgba(255,255,255,.4);margin-bottom:3px">'+m.l+'</div>'+
            '<div style="font-size:13px;font-weight:700;color:'+wc+';font-variant-numeric:tabular-nums">'+m.v+'</div></div>';
        }).join('')+'</div>';
    }
    var icText=document.getElementById('ic-text');if(icText)icText.innerHTML=bandaHtml+bodyHtml+detailHtml;
    set('ic-date','Actualizado hoy '+t+' · telemetría real del dispositivo');
    var rate=null;
    if(D.piscH.length>=3){var rec=D.piscH.slice(-4);if(rec.length>=2){var dt_h=(rec[rec.length-1].ts-rec[0].ts)/3600000;if(dt_h>0)rate=(rec[rec.length-1].v-rec[0].v)/dt_h;}}
    if(calOn&&rate!==null&&rate>0){
      set('icm-1','+'+rate.toFixed(2)+'°C/h');set('icm-1s','tasa de calentamiento');
      var rem=tCur!==null&&tCur<TEMP_OBJ?(TEMP_OBJ-tCur)/rate:0;
