  /* ── 12. RENDER SEC04 ──────────────────────────────────── */
  function renderSec04(){
    var pw=lat(D.ilu,'potencia_activa'),enAc=lat(D.ilu,'energia_acumulada'),volt=lat(D.ilu,'voltaje'),curr=lat(D.ilu,'corriente');
    if(pw!==null)   set('cs-now',pw.toFixed(0)+' W');
    if(volt!==null) set('cs-v',volt.toFixed(1)+' V');
    if(curr!==null) set('cs-i2',curr.toFixed(2)+' A');
    if(enAc!==null) set('cc-acum',(enAc/1000).toFixed(2)+' kWh');
    set('cc-tar',TARIFA.toFixed(2));
    var enToday=estimateEnergyToday();
    if(enToday!==null){
      set('cs-en',enToday.toFixed(2)+' kWh'); set('cc-hoy',fmtSol(enToday*TARIFA));
      var now=new Date(),daysM=new Date(now.getFullYear(),now.getMonth()+1,0).getDate();
      var hElapsed=Math.max((nowMs()-todayStart())/3600000,0.5),proj=(enToday/hElapsed*24)*daysM;
      set('cc-proj','~'+proj.toFixed(1)+' kWh ≈ '+fmtSol(proj*TARIFA));
    }
  }

  function estimateEnergyToday(){
    if(!D.iluH||D.iluH.length<2) return null;
    var today=D.iluH.filter(function(p){return p.ts>=todayStart();}); if(today.length<2) return null;
    var kwh=0;
    for(var i=1;i<today.length;i++){var dt_h=(today[i].ts-today[i-1].ts)/3600000;kwh+=((today[i].v+today[i-1].v)/2/1000)*dt_h;}
    return kwh;
  }

