    document.addEventListener('click',function(){dd.style.display='none';});
  })();

  /* ── ARRANQUE ──────────────────────────────────────────── */
  function loadAll(){
    loadServerAttributes();
    loadCalLatest(); loadIluLatest(); loadAmbLatest();
    loadPiscH(); loadIluH(); loadPiscYd(); loadAlarms();
  }
  loadAll();

  /* ── RESPONSIVE ────────────────────────────────────────── */
  function applyResponsive(){
    var root=document.getElementById('exp-root'),body=document.getElementById('exp-body'),right=document.getElementById('exp-right'),sub=document.getElementById('exp-subtitle');
    if(!root||!body) return;
    var w=root.offsetWidth||1200;
    if(w<=600){body.style.gridTemplateColumns='1fr';if(right)right.style.order='-1';if(sub)sub.style.display='none';}
    else if(w<=900){body.style.gridTemplateColumns='1fr';if(right)right.style.order='';if(sub)sub.style.display='';}
    else{body.style.gridTemplateColumns='3fr 2fr';if(right)right.style.order='';if(sub)sub.style.display='';}
  }
  applyResponsive(); window.addEventListener('resize',applyResponsive);

  /* ── REPORTE PDF ───────────────────────────────────────────── */
  function generatePDF(){
    var btn=document.querySelector('.act-btn.act-teal');
    if(btn){btn.querySelector('.act-t').textContent='Generando…';}
    function withJsPDF(cb){
      if(window.jspdf&&window.jspdf.jsPDF){cb(window.jspdf.jsPDF);return;}
      var s=document.createElement('script');s.src='https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js';
      s.onload=function(){cb(window.jspdf.jsPDF);};
      s.onerror=function(){if(btn)btn.querySelector('.act-t').textContent='Error al cargar PDF';};
      document.head.appendChild(s);
    }
    withJsPDF(function(jsPDF){
      var doc=new jsPDF({orientation:'portrait',unit:'mm',format:'a4'});
      var W=210,H=297,NAVY=[0,0,140],TEAL=[0,235,200],GRAY=[90,110,138],LIGHT=[235,240,247],DARK=[13,27,46];
      var now=new Date(),MESES=['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
      var año=now.getFullYear();
      /* ── Portada ── */
      doc.setFillColor.apply(doc,NAVY);doc.rect(0,0,W,H,'F');
      doc.setFillColor.apply(doc,TEAL);doc.rect(0,0,W,4,'F');
      doc.setFontSize(28);doc.setFont('helvetica','bold');doc.setTextColor(255,255,255);doc.text('sun',47,38);
      doc.setTextColor.apply(doc,TEAL);doc.text('KUU',66,38);
      doc.setFontSize(10);doc.setFont('helvetica','normal');doc.setTextColor(180,180,200);doc.text('360',84,38);
      doc.setFontSize(22);doc.setFont('helvetica','bold');doc.setTextColor(255,255,255);doc.text('Informe operativo',20,90);
      doc.setTextColor.apply(doc,TEAL);doc.text('Piscina Temperada',20,103);
      doc.setTextColor(255,255,255);doc.setFontSize(13);doc.setFont('helvetica','normal');doc.text(INSTALL_NAME,20,118);
      doc.setFontSize(11);doc.setTextColor(180,180,200);
      doc.text(MESES[now.getMonth()].charAt(0).toUpperCase()+MESES[now.getMonth()].slice(1)+' '+año+' · Generado '+pad(now.getDate())+'/'+pad(now.getMonth()+1)+'/'+año+' '+pad(now.getHours())+':'+pad(now.getMinutes()),20,132);
      doc.setDrawColor.apply(doc,TEAL);doc.setLineWidth(0.5);doc.line(20,142,W-20,142);
      /* KPIs portada */
      var tCur=lat(D.pisc,'temperatura_sonda'),calOn=lat(D.pisc,'estado_salida'),ta=lat(D.amb,'temperatura');
      if(tCur!==null){
        var kpis=[
          {l:'Temperatura piscina',v:fmtT(tCur)+'°C'},
          {l:'Objetivo configurado',v:TEMP_OBJ+'°C'},
          {l:'Calentador',         v:calOn===null?'—':(calOn?'Encendido':'Apagado')},
          {l:'Temp. ambiente',     v:ta!==null?fmtT(ta)+'°C':'—'}
        ];
        kpis.forEach(function(k,i){
          var x=20+(i%2)*85,y=160+Math.floor(i/2)*28;
          doc.setFillColor(255,255,255,8);doc.roundedRect(x,y-6,80,22,2,2,'F');
          doc.setFontSize(8);doc.setFont('helvetica','normal');doc.setTextColor(160,180,210);doc.text(k.l.toUpperCase(),x+6,y+1);
          doc.setFontSize(14);doc.setFont('helvetica','bold');doc.setTextColor.apply(doc,TEAL);doc.text(k.v,x+6,y+11);
        });
      }
      doc.setFontSize(8);doc.setFont('helvetica','normal');doc.setTextColor(100,120,150);
      doc.text('Plataforma de monitoreo energético · Sunkuu 360 · Generado automáticamente',W/2,H-12,{align:'center'});
      doc.text('GONEX S.A.C. · gonex.pe',W/2,H-7,{align:'center'});
      /* ── Página 2: Análisis ── */
      doc.addPage();
      doc.setFillColor.apply(doc,NAVY);doc.rect(0,0,W,18,'F');
      doc.setFontSize(9);doc.setFont('helvetica','bold');doc.setTextColor.apply(doc,TEAL);doc.text('SUNKUU 360',12,11);
      doc.setTextColor(255,255,255);doc.setFont('helvetica','normal');doc.text('· Informe operativo — '+INSTALL_NAME,38,11);
      doc.setTextColor(150,170,191);doc.text(pad(now.getDate())+'/'+pad(now.getMonth()+1)+'/'+año,W-12,11,{align:'right'});
      var yP=32;
      doc.setFillColor.apply(doc,TEAL);doc.rect(12,yP-5,3,14,'F');
      doc.setFontSize(14);doc.setFont('helvetica','bold');doc.setTextColor.apply(doc,NAVY);doc.text('Estado operativo',18,yP+5);yP+=18;
      /* Estado clasificado */
      var state=classifyPiscState();
      var stateColor=state.level==='estable'?[16,185,129]:state.level==='atencion'?[245,158,11]:[150,170,191];
      doc.setFillColor.apply(doc,stateColor);doc.roundedRect(15,yP-4,W-30,10,2,2,'F');
      doc.setFontSize(10);doc.setFont('helvetica','bold');doc.setTextColor(255,255,255);
      doc.text(state.badge.toUpperCase(),W/2,yP+3,{align:'center'});yP+=16;
      doc.setFontSize(10);doc.setFont('helvetica','normal');doc.setTextColor.apply(doc,DARK);
      var lines=doc.splitTextToSize(state.title,W-30);doc.text(lines,15,yP);yP+=lines.length*6+4;
      if(state.impact){
        doc.setFontSize(9);doc.setTextColor.apply(doc,GRAY);
        var iLines=doc.splitTextToSize('Impacto potencial: '+state.impact,W-30);doc.text(iLines,15,yP);yP+=iLines.length*6+8;
      }
      /* Historial temperatura */
      if(D.piscH&&D.piscH.length>0){
        yP+=4;doc.setFillColor.apply(doc,TEAL);doc.rect(12,yP-5,3,14,'F');
        doc.setFontSize(12);doc.setFont('helvetica','bold');doc.setTextColor.apply(doc,NAVY);doc.text('Temperatura últimas 24h',18,yP+5);yP+=14;
        var vals=D.piscH.map(function(p){return p.v;});
        var maxV=Math.max.apply(null,vals),minV=Math.min.apply(null,vals);
        doc.setFontSize(9);doc.setFont('helvetica','normal');doc.setTextColor.apply(doc,DARK);
        doc.text('Máxima: '+fmtT(maxV)+'°C  ·  Mínima: '+fmtT(minV)+'°C  ·  Rango: '+(maxV-minV).toFixed(1)+'°C  ·  Objetivo: '+TEMP_OBJ+'°C',15,yP);yP+=12;
      }
      /* Alarmas */
      yP+=4;doc.setFillColor.apply(doc,TEAL);doc.rect(12,yP-5,3,14,'F');
      doc.setFontSize(12);doc.setFont('helvetica','bold');doc.setTextColor.apply(doc,NAVY);doc.text('Historial de alarmas',18,yP+5);yP+=14;
      var activeAlarms=D.alarms.filter(function(a){return a.status&&a.status.indexOf('ACTIVE')>=0;});
      if(D.alarms.length===0){
        doc.setFontSize(10);doc.setFont('helvetica','normal');doc.setTextColor(16,185,129);doc.text('✓ Sin alarmas activas ni recientes.',15,yP);
      } else {
        D.alarms.slice(0,5).forEach(function(a){
          var sev=a.severity||'WARNING';
          var col2=sev==='CRITICAL'?[239,68,68]:sev==='MAJOR'?[245,158,11]:[99,102,241];
          doc.setFillColor.apply(doc,col2);doc.rect(15,yP-3,2,7,'F');
          doc.setFontSize(9);doc.setFont('helvetica','bold');doc.setTextColor.apply(doc,DARK);
          doc.text((a.type||'Alarma')+' · '+sev,20,yP+1);
          if(a.createdTime){var d2=new Date(a.createdTime);doc.setFont('helvetica','normal');doc.setTextColor.apply(doc,GRAY);doc.text(pad(d2.getDate())+'/'+pad(d2.getMonth()+1)+' '+pad(d2.getHours())+':'+pad(d2.getMinutes()),W-15,yP+1,{align:'right'});}
          yP+=8;
        });
      }
      /* Footer */
      doc.setFillColor.apply(doc,LIGHT);doc.rect(0,H-14,W,14,'F');
      doc.setFontSize(8);doc.setFont('helvetica','normal');doc.setTextColor.apply(doc,GRAY);
      doc.text('Sunkuu 360 · Informe generado automáticamente · '+pad(now.getDate())+'/'+pad(now.getMonth()+1)+'/'+año,W/2,H-5,{align:'center'});
      var fn='sunkuu360-piscina-'+año+pad(now.getMonth()+1)+pad(now.getDate())+'.pdf';
      doc.save(fn);
      if(btn) btn.querySelector('.act-t').textContent='Generar Reporte PDF';
    });
  }
  /* Conectar botón PDF piscina */
  (function(){
    var btnPdf=document.querySelector('.act-btn.act-teal');
    if(btnPdf) btnPdf.addEventListener('click',generatePDF);
  })();

  var tR=setInterval(function(){loadCalLatest();loadIluLatest();loadAmbLatest();},30000);
  var tH=setInterval(function(){loadPiscH();loadIluH();},600000);
  self.onDestroy=function(){clearInterval(tR);clearInterval(tH);Object.keys(CH).forEach(function(k){if(CH[k]){try{CH[k].destroy();}catch(e){}CH[k]=null;}});};
};

